module firr18_v5 (
    input  wire        clk,
    input  wire        rst_n,
    input  wire [7:0]  x,
    output reg  [15:0] y
);
    reg  [7:0]  xs [0:17];
    integer     i;
    reg  [23:0] acc;
    always @(*) acc = 8'd1 * xs[0] + 8'd3 * xs[1] + 8'd7 * xs[2] + 8'd15 * xs[3] + 8'd31 * xs[4] + 8'd63 * xs[5] + 8'd127 * xs[6] + 8'd255 * xs[7] + 8'd511 * xs[8] + 8'd1023 * xs[9] + 8'd2047 * xs[10] + 8'd4095 * xs[11] + 8'd8191 * xs[12] + 8'd16383 * xs[13] + 8'd32767 * xs[14] + 8'd65535 * xs[15] + 8'd131071 * xs[16] + 8'd262143 * xs[17];
    always @(posedge clk) begin
        if (!rst_n) begin
            for (i = 0; i < 18; i = i + 1) xs[i] <= 8'd0;
            y <= 16'd0;
        end else begin
            xs[0] <= x;
            for (i = 1; i < 18; i = i + 1) xs[i] <= xs[i-1];
            y <= acc[15:0];
        end
    end
endmodule

